findings.codeql_raw_query:
/**
 * @name Potential command injection via os.system/subprocess
 * @description Finds flows of untrusted data into os.system/popen or subprocess execution
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection-backend
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

class CommandExecSink extends DataFlow::Node {
  CommandExecSink() { this instanceof CodeExecution }
}

module CmdConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    sink instanceof CodeExecution
  }
}

module CmdFlow = TaintTracking::Global<CmdConfig>;
import CmdFlow::PathGraph

from CmdFlow::PathNode source, CmdFlow::PathNode sink
where CmdFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches a command execution sink.", source.getNode(), "user input"
